# ─────────────────────────── Tự luận: ví dụ D2, D5, bài E1–E12, bài nâng cao G1–G4 ───────────────────────────
def lg(items):
    out = ""
    for kind, x in items:
        out += f"<p>{x}</p>" if kind == "p" else f"$${x}$$"
    return out

def bai(k, muc, de, items):
    return f'<h4>Bài {k} · {muc}</h4>{de}<details><summary>Hướng dẫn giải</summary>{lg(items)}</details>'

